const { chromium } = require('/tmp/node_modules/playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const cssPath  = path.resolve('styles.css');
  const compPath = path.resolve('components.js');
  const appPath  = path.resolve('app.js');

  // Inline all assets so the page renders fully without a server
  const css  = fs.readFileSync(cssPath,  'utf8');
  const comp = fs.readFileSync(compPath, 'utf8');
  const app  = fs.readFileSync(appPath,  'utf8');

  const fullHtml = html
    .replace('<link rel="stylesheet" href="styles.css" />', `<style>${css}</style>`)
    .replace('<script src="components.js"></script>', `<script>${comp}</script>`)
    .replace('<script src="app.js"></script>', `<script>${app}</script>`);

  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(fullHtml, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Run axe on the default (closed dialog) state
  const r1 = await page.evaluate(async () => await window.axe.run());

  // Open the dialog and run axe again
  await page.click('#delete-trigger');
  await page.waitForTimeout(200);
  const r2 = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  const format = v => ({ id: v.id, impact: v.impact, tags: v.tags, nodes: v.nodes.map(n => n.target) });
  const report = {
    closed: {
      wcag: r1.violations.filter(v => !v.tags.includes('best-practice')).map(format),
      bp:   r1.violations.filter(v =>  v.tags.includes('best-practice')).map(format),
    },
    open: {
      wcag: r2.violations.filter(v => !v.tags.includes('best-practice')).map(format),
      bp:   r2.violations.filter(v =>  v.tags.includes('best-practice')).map(format),
    },
  };
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
  process.exit(report.closed.wcag.length || report.open.wcag.length ? 1 : 0);
})();
EOF
