/* ─── Reset / base ──────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  color: var(--color-text-primary);
  background: var(--color-bg);
  min-height: 100dvh;
}

img { display: block; max-width: 100%; }

/* ─── Skip link ─────────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-surface);
  color: var(--color-accent);
  font-weight: 600;
  border: 2px solid var(--color-border-focus);
  border-radius: var(--radius-sm);
  z-index: 9999;
  text-decoration: none;
}
.skip-link:focus { top: 1rem; }

/* ─── Header ────────────────────────────────────────────────────────────── */
.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2rem;
  height: 60px;
  background: #0f172a;
  border-bottom: 1px solid #1e293b;
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header__logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  color: #f8fafc;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -.01em;
  text-decoration: none;
}

.site-header__logo svg { flex-shrink: 0; }

.site-header__nav {
  display: flex;
  align-items: center;
  gap: .25rem;
}

.header-nav-link {
  color: #94a3b8;
  font-size: .875rem;
  font-weight: 500;
  text-decoration: none;
  padding: .375rem .75rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.header-nav-link:hover { color: #f1f5f9; background: rgba(255,255,255,.07); }
.header-nav-link:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 2px;
  color: #f1f5f9;
}
.header-nav-link[aria-current="page"] { color: #f1f5f9; }

/* ─── Breadcrumb ────────────────────────────────────────────────────────── */
.breadcrumb-bar {
  padding: .875rem 2rem;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: .5rem;
  list-style: none;
  font-size: .8125rem;
  color: var(--color-text-secondary);
}

.breadcrumb a {
