}
.breadcrumb a:hover { text-decoration: underline; }
.breadcrumb a:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 2px;
  border-radius: 2px;
}
.breadcrumb__sep { color: var(--color-border); }

/* ─── Main layout ───────────────────────────────────────────────────────── */
.preview-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 1.5rem;
