  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem;
  align-items: start;
}

@media (max-width: 900px) {
  .preview-layout { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .preview-layout { padding: 1rem; gap: 1rem; }
  .breadcrumb-bar { padding: .75rem 1rem; }
  .site-header { padding: 0 1rem; }
}

/* ─── Image viewer ──────────────────────────────────────────────────────── */
.image-viewer {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}

.image-viewer__canvas {
  background: #0f172a;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 420px;
  padding: 1.5rem;
}

.image-viewer__img {
  border-radius: var(--radius-md);
  max-height: 520px;
  width: 100%;
  object-fit: contain;
}

.image-viewer__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: .75rem 1rem;
  border-top: 1px solid var(--color-border);
  background: var(--color-surface-alt);
  gap: .5rem;
  flex-wrap: wrap;
}

.image-viewer__nav {
  display: flex;
  align-items: center;
  gap: .25rem;
}

.toolbar-btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .4rem .75rem;
  font-size: .8125rem;
  font-weight: 500;
  font-family: var(--font);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-surface);
  color: var(--color-text-primary);
