  white-space: nowrap;
}
.toolbar-btn:hover { background: var(--color-bg); border-color: #adb5bd; }
.toolbar-btn:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 2px;
}
.toolbar-btn svg { flex-shrink: 0; }
.toolbar-btn--icon {
  padding: .4rem .5rem;
}

/* ─── Sidebar / metadata panel ──────────────────────────────────────────── */
.metadata-panel {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.metadata-panel__section {
  padding: 1.25rem 1.25rem 0;
}

.metadata-panel__section + .metadata-panel__section {
  margin-top: 1.25rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--color-border);
}

.metadata-panel__section:last-child { padding-bottom: 1.25rem; }

.metadata-panel__label {
  font-size: .6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .07em;
  color: var(--color-text-secondary);
  margin-bottom: .75rem;
}

.metadata-panel__filename {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.3;
  word-break: break-all;
}

.metadata-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  font-size: .8125rem;
  padding: .3rem 0;
}
.metadata-row:not(:last-child) { border-bottom: 1px solid #f1f3f5; }
.metadata-row__key { color: var(--color-text-secondary); }
.metadata-row__val { font-weight: 500; text-align: right; }

/* Tag chips */
.tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: .375rem;
  list-style: none;
}
.tag-list__item {
  font-size: .75rem;
  font-weight: 500;
  padding: .2rem .6rem;
  border-radius: 999px;
  background: #e0e7ff;
  color: #3730a3;
}

/* ─── Action buttons ────────────────────────────────────────────────────── */
.action-bar {
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .625rem 1rem;
  font-size: .875rem;
  font-weight: 600;
  font-family: var(--font);
  border-radius: var(--radius-md);
  cursor: pointer;
  border: 1px solid transparent;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  width: 100%;
  white-space: nowrap;
}
.btn:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 2px;
}

.btn--primary {
  background: var(--color-accent);
  color: #fff;
}
.btn--primary:hover { background: var(--color-accent-hover); }

.btn--secondary {
  background: var(--color-surface);
  color: var(--color-text-primary);
  border-color: var(--color-border);
}
.btn--secondary:hover { background: var(--color-bg); border-color: #adb5bd; }

.btn--danger-outline {
  background: transparent;
  color: var(--color-danger);
  border-color: var(--color-danger-border);
}
.btn--danger-outline:hover {
  background: var(--color-danger-subtle);
  border-color: var(--color-danger);
}

/* ─── Thumbnail strip ───────────────────────────────────────────────────── */
.thumbnail-strip-section {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 2rem 2rem;
}

.thumbnail-strip__heading {
  font-size: .8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .07em;
  /* #4b5563 on #f1f3f5 = 5.84:1 contrast — passes WCAG AA for small text */
  color: #4b5563;
  margin-bottom: .75rem;
}

.thumbnail-strip {
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  padding-bottom: .5rem;
  scrollbar-width: thin;
  list-style: none;
}

.thumbnail-strip > li { display: contents; }

.thumbnail {
  flex-shrink: 0;
  width: 96px;
  height: 72px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 2px solid transparent;
  cursor: pointer;
  transition: border-color var(--transition);
  background: #1e293b;
}
.thumbnail:hover { border-color: var(--color-accent); }
.thumbnail[aria-current="true"] { border-color: var(--color-accent); }
.thumbnail:focus-visible {
  outline: 2px solid var(--color-border-focus);
  outline-offset: 2px;
}
.thumbnail img { width: 100%; height: 100%; object-fit: cover; }

/* ─── Dialog ────────────────────────────────────────────────────────────── */
dialog {
  padding: 0;
  border: none;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  background: var(--color-surface);
  max-width: min(440px, calc(100vw - 2rem));
  width: 100%;
}

dialog::backdrop {
  background: rgba(15, 23, 42, .55);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

.dialog__inner {
  padding: 1.75rem;
}

.dialog__icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-danger-subtle);
  border: 1px solid var(--color-danger-border);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--color-danger);
}

.dialog__heading {
  font-size: 1.125rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: .5rem;
  color: var(--color-text-primary);
}

.dialog__body {
  font-size: .9375rem;
  color: var(--color-text-secondary);
  margin-bottom: .25rem;
  line-height: 1.6;
}

.dialog__filename-callout {
  display: flex;
  align-items: center;
  gap: .5rem;
  background: var(--color-surface-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: .5rem .75rem;
  font-size: .875rem;
  font-weight: 500;
  margin: .875rem 0;
  color: var(--color-text-primary);
}

.dialog__filename-callout svg { flex-shrink: 0; color: var(--color-text-secondary); }

.dialog__warning {
  font-size: .8125rem;
  color: var(--color-danger);
  font-weight: 500;
  margin-top: .25rem;
}

.dialog__actions {
  display: flex;
  gap: .625rem;
  margin-top: 1.5rem;
}

.dialog__actions .btn { flex: 1; }

/* ─── Reduced motion ────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ─── Forced colors ─────────────────────────────────────────────────────── */
@media (forced-colors: active) {
  .btn, .toolbar-btn { border: 2px solid ButtonText; }
  .btn--primary { background: Highlight; color: HighlightText; }
  .thumbnail[aria-current="true"] { border-color: Highlight; }
  dialog { border: 2px solid CanvasText; }
}
