const { chromium } = require('/tmp/node_modules/playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css',    'utf8');
  const comp = fs.readFileSync('components.js', 'utf8');
  const app  = fs.readFileSync('app.js',        'utf8');

  const fullHtml = html
    .replace('<link rel="stylesheet" href="styles.css" />', `<style>${css}</style>`)
    .replace('<script src="components.js"></script>', `<script>${comp}</script>`)
    .replace('<script src="app.js"></script>', `<script>${app}</script>`);

  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(fullHtml, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  const r1 = await page.evaluate(async () => await window.axe.run());

  await page.click('#delete-trigger');
  await page.waitForTimeout(200);
  const r2 = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  const fmt = v => ({ id: v.id, impact: v.impact, nodes: v.nodes.map(n => n.target) });
  const report = {
    'closed-WCAG': r1.violations.filter(v => !v.tags.includes('best-practice')).map(fmt),
    'closed-BP':   r1.violations.filter(v =>  v.tags.includes('best-practice')).map(fmt),
    'open-WCAG':   r2.violations.filter(v => !v.tags.includes('best-practice')).map(fmt),
    'open-BP':     r2.violations.filter(v =>  v.tags.includes('best-practice')).map(fmt),
  };
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
  const wcagCount = report['closed-WCAG'].length + report['open-WCAG'].length;
  process.exit(wcagCount ? 1 : 0);
})();
EOF
